 "content": "from collections import Counter
from functools import reduce
from math import gcd


def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(value for row in grid for value in row)
    common = {value for value, _ in counts.most_common(2)}
    background = counts.most_common(1)[0][0]
    markers = [(r, c) for r in range(h) for c in range(w)
               if grid[r][c] not in common]
    if not markers:
        return [[background]]

    def lattice_coords(values):
        values = sorted(set(values))
        if len(values) < 2:
            return values
        step = reduce(gcd, (b - a for a, b in zip(values, values[1:])))
        if step == 0:
            return values
        # Missing marker positions are ordinary lattice intersections; fill
        # them in only between the first and last observed marked lines.
        return list(range(values[0], values[-1] + 1, step))

    rows = lattice_coords(r for r, _ in markers)
    cols = lattice_coords(c for _, c in markers)
    if len(rows) < 2 or len(cols) < 2:
        return [[background]]

    result = []
    for r0, r1 in zip(rows, rows[1:]):
        out_row = []
        for c0, c1 in zip(cols, cols[1:]):
            corners = (grid[r0][c0], grid[r0][c1],
                       grid[r1][c0], grid[r1][c1])
            value = corners[0]
            if value not in common and all(v == value for v in corners):
                out_row.append(value)
            else:
                out_row.append(background)
        result.append(out_row)
    return result


